+
+/**
+ * Cart page of the TestverQA shop.
+ *
+ * Confirmed live (guest, staging):
+ * line items with qty (data-testid="qty-N"),
+ * remove (data-testid="remove-N"), coupon application via data-testid="coupon-input"
+ * + "apply-coupon" (SAVE10 → -10%, WELCOME20 → -20%, EXPIRED/MAXEDOUT → errors),
+ * order summary rows (Subtotal / Discount / Shipping / Tax (8%) / Total) and
+ * "#coupon-msg" feedback. "Proceed to checkout" → /shop/checkout/{n}.
+ */
+export class CartPage extends BasePage {
+  readonly page: Page;
+  readonly heading: Locator;
+  readonly couponInput: Locator;
+  readonly applyCouponButton: Locator;
+  readonly couponMessage: Locator;
+  readonly checkoutLink: Locator;
+  readonly itemCount: Locator;
+  /** "Subtotal" amount in the cart order summary, e.g. "$1978.00". */
+  readonly subtotalAmount: Locator;
+  /** "Discount" amount row, rendered only once a coupon is accepted, e.g. "-$296.70". */
+  readonly discountAmount: Locator;
+  /** "Total" amount in the cart order summary, e.g. "$2146.23". */
+  readonly totalAmount: Locator;
+  /** "Proceed to checkout" CTA beneath the order summary. */
+  readonly proceedToCheckoutButton: Locator;
+  /** "×" remove control on the first cart row (remove-1). */
+  readonly removeItemButton: Locator;
+
+  constructor(page: Page) {
+    super(page);
+    this.page = page;
+    this.heading = page.getByRole('heading', { level: 1 });
+    this.couponInput = page.getByTestId('coupon-input');
+    this.applyCouponButton = page.getByTestId('apply-coupon');
+    this.couponMessage = page.locator('#coupon-msg');
+    this.checkoutLink = page.getByRole('link', { name: /Proceed to checkout/ });
+    this.itemCount = page.locator('p', { hasText: /item\(s\)/ });
+    this.subtotalAmount = page.getByTestId('sum-subtotal');
+    this.discountAmount = page.getByTestId('sum-discount');
+    this.totalAmount = page.getByTestId('sum-total');
+    this.proceedToCheckoutButton = page.getByTestId('checkout-btn');
+    this.removeItemButton = page.getByTestId('remove-1');
+  }
+
+  async expectLoaded(): Promise<void> {
