+      const amount = text.match(/-?\$([0-9][0-9,]*\.?[0-9]*)/);
+      if (!label || !amount) {
+        continue;
+      }
+      const key = label[1].trim().toLowerCase().replace(/\s*\(.*\)$/, '');
+      summary[key] = Number(amount[1].replace(/,/g, ''));
+    }
+
+    // The Total cell carries its own test id — always prefer it.
+    const totalText = await this.page.getByTestId('sum-total').innerText();
+    const total = totalText.match(/-?\$([0-9][0-9,]*\.?[0-9]*)/);
+    if (total) {
+      summary.total = Number(total[1].replace(/,/g, ''));
+    }
+    return summary;
+  }
+
+  /**
+   * Dollar amount of an order-summary test-id cell ("sum-subtotal",
+   * "sum-discount", "sum-shipping", "sum-tax", "sum-total") as a number.
+   * Returns null when the cell is absent (no coupon applied => no discount row).
+   */
+  async amount(cell: string): Promise<number | null> {
+    const locator = this.page.getByTestId(cell);
+    if ((await locator.count()) === 0) {
+      return null;
+    }
+    return parseAmount(await locator.innerText());
+  }
+
+  /** Wait until the coupon feedback line reads the expected message. */
+  async expectCouponMessage(message: string): Promise<void> {
+    await expect(this.couponMessage).toHaveText(message, { timeout: 15000 });
+  }
+
+  /** The empty-cart state ("Your cart is empty") rendered on the cart page. */
+  async expectEmpty(): Promise<void> {
+    await expect(this.page.getByRole('heading', { name: 'Your cart is empty' })).toBeVisible();
+  }
+}
+
+/** Strip the currency formatting from a "$12,345.67" / "-$296.70" string. */
+export function parseAmount(text: string): number {
+  const match = text.match(/-?\$([0-9][0-9,]*\.?[0-9]*)/);
+  if (!match) {
+    throw new Error(`No dollar amount found in "${text}"`);
+  }
+  const value = Number(match[1].replace(/,/g, ''));
+  return text.trim().startsWith('-') ? -value : value;
+}

