+import { test, expect } from '../fixtures/fixtures';
+import { dismissConsent } from '../helpers/consent';
+import { parseAmount } from '../pages/CartPage';
+import { CART_TITLE } from '../pages/CartPage';
+import { SHOP_TITLE } from '../pages/ShopPage';
+
+/**
+ * REQ-SHOP-04 "Shop coupons and checkout" — Coupons (source SRC-4).
+ *
+ *   SAVE10 takes 10% off the cart subtotal.
+ *   WELCOME20 takes 20% off the cart subtotal.
+ *   An expired coupon is refused with the message "Coupon expired".
+ *   An unknown code is refused with the message "Invalid coupon code".
+ *
+ * Journey: guest enters the shop from the home page, adds the first product,
+ * opens the cart through the header "🛒 Cart (n)" badge and applies a coupon.
+ *
+ * Isolation without /api (a declared restriction, so POST /api/reset is not
+ * available here): every test gets a brand-new browser context, whose guest
+ * session starts with an empty cart — so exactly one product is in the cart.
+ */
+
+const COUPON_TOLERANCE = 0.02;
+
+/** Guest journey: home page -> Shop module -> add the first product -> cart. */
+async function guestReachesCartWithOneProduct(
+  page: import('@playwright/test').Page,
+  shopPage: import('../pages/ShopPage').ShopPage,
+  cartPage: import('../pages/CartPage').CartPage,
+): Promise<void> {
+  await page.goto('/');
+  await dismissConsent(page);
+
+  // The shop module link on the home page (E-commerce Flow card).
+  await page.getByTestId('module-link-shop').click();
+  await expect(page).toHaveTitle(SHOP_TITLE);
+  await expect(shopPage.heading).toHaveText('Shop');
+
+  await shopPage.addFirstProductToCart();
+  // The add is an async request — wait for the badge before navigating away.
+  await expect(shopPage.cartCount).toHaveText('1');
+
+  await shopPage.cartLink.click();
+  await expect(page).toHaveTitle(CART_TITLE);
+  await expect(cartPage.heading).toHaveText('Your cart');
+}
+
+/** Assert the applied coupon cut exactly `percent` off the subtotal. */
+async function expectPercentOffSubtotal(
+  cartPage: import('../pages/CartPage').CartPage,
+  percent: number,
+): Promise<void> {
+  // The summary re-renders asynchronously once the coupon is accepted.
+  await cartPage.expectDiscountApplied();
+
+  const subtotal = await cartPage.amount('sum-subtotal');
+  const discount = await cartPage.amount('sum-discount');
+  const shipping = await cartPage.amount('sum-shipping');
+  const tax = await cartPage.amount('sum-tax');
+  const total = await cartPage.amount('sum-total');
+
+  expect(subtotal, 'cart subtotal should be readable').not.toBeNull();
+  expect(discount, 'a discount row should be present').not.toBeNull();
+  expect(total, 'cart total should be readable').not.toBeNull();
+
+  // The discount is shown as a negative amount; compare magnitudes.
+  const discountMagnitude = Math.abs(discount as number);
+  const expectedDiscount = (subtotal as number) * percent;
+
+  expect(
+    Math.abs(discountMagnitude - expectedDiscount),
+    `discount ${discountMagnitude} should be ${percent * 100}% of subtotal ${subtotal}`,
+  ).toBeLessThanOrEqual(COUPON_TOLERANCE);
+
+  // The total still reconciles: subtotal - discount + shipping + tax.
+  const expectedTotal =
+    (subtotal as number) - discountMagnitude + (shipping ?? 0) + (tax ?? 0);
+  expect(Math.abs((total as number) - expectedTotal)).toBeLessThanOrEqual(COUPON_TOLERANCE);
+}
+
+test('Shop coupons: SAVE10 takes 10 percent off the cart subtotal', async ({
+  page,
+  shopPage,
+  cartPage,
+}) => {
+  await guestReachesCartWithOneProduct(page, shopPage, cartPage);
+
+  await cartPage.applyCoupon('SAVE10');
+  await expectPercentOffSubtotal(cartPage, 0.1);
+});
+
+test('Shop coupons: WELCOME20 takes 20 percent off the cart subtotal', async ({
+  page,
+  shopPage,
+  cartPage,
+}) => {
+  await guestReachesCartWithOneProduct(page, shopPage, cartPage);
+
+  await cartPage.applyCoupon('WELCOME20');
+  await expectPercentOffSubtotal(cartPage, 0.2);
+});
+
+test('Shop coupons: an expired coupon is refused with Coupon expired', async ({
+  page,
+  shopPage,
+  cartPage,
+}) => {
+  await guestReachesCartWithOneProduct(page, shopPage, cartPage);
+
+  await cartPage.applyCoupon('EXPIRED');
+
+  await cartPage.expectCouponMessage('Coupon expired');
+  // A refused coupon must not discount the order.
+  expect(await cartPage.discountText()).toBe('');
+  expect(await cartPage.discountAmount.count()).toBe(0);
+});
+
+test('Shop coupons: an unknown code is refused with Invalid coupon code', async ({
+  page,
+  shopPage,
+  cartPage,
+}) => {
+  await guestReachesCartWithOneProduct(page, shopPage, cartPage);
+
+  await cartPage.applyCoupon('NOTACODE');
+
+  await cartPage.expectCouponMessage('Invalid coupon code');
+  // A refused coupon must not discount the order.
+  expect(await cartPage.discountText()).toBe('');
+  expect(await cartPage.discountAmount.count()).toBe(0);
+});
+
+test('Shop coupons: the cart subtotal is the sum of the line items', async ({
+  page,
+  shopPage,
+  cartPage,
+}) => {
+  await guestReachesCartWithOneProduct(page, shopPage, cartPage);
+
+  // Cart table: Product | Price | Qty | Subtotal
+  const rowText = await page.getByTestId('cart-table').locator('tbody tr').first().innerText();
+  const price = parseAmount(rowText);
+  const subtotal = await cartPage.amount('sum-subtotal');
+
+  expect(subtotal).not.toBeNull();
+  expect(Math.abs((subtotal as number) - price)).toBeLessThanOrEqual(COUPON_TOLERANCE);
+});
+

