+import { test, expect, type Page } from '@playwright/test';
+import { dismissConsent } from '../helpers/consent';
+import { ShopPage, SHOP_TITLE } from '../pages/ShopPage';
+import { CartPage, CART_TITLE } from '../pages/CartPage';
+import { CheckoutPage, CHECKOUT_TITLE, ORDER_CONFIRMED_HEADING } from '../pages/CheckoutPage';
