+/**
+ * REQ-SHOP-04 "Shop coupons and checkout" — Checkout (source SRC-4).
+ *
+ *   Checkout has five steps and ends on an order confirmation page that
+ *   shows the order number.
+ *   The cart is empty after an order is placed.
+ *
+ * Journey: guest enters the shop from the home page, adds the first product,
+ * opens the cart from the header badge, proceeds to checkout, walks all five
+ * steps (shipping -> billing -> method -> payment -> review) with the sandbox
+ * test card, places the order and ends on the confirmation page.
+ *
+ * Isolation without /api (a declared restriction): each test uses a fresh
+ * browser context, so the guest cart starts empty and holds one product.
+ */
+
+/** The five checkout steps, in order, as shown by the stepper and page header. */
+const CHECKOUT_STEPS = ['Shipping', 'Billing', 'Method', 'Payment', 'Review'];
+
+const SHIPPING = {
+  name: 'Ada Lovelace',
+  phone: '+1 555 0100',
+  address: '42 Analytical Lane',
+  city: 'London',
+  zip: '10001',
+};
+
+/** Guest journey: home -> shop tile -> add first product -> cart. */
+async function guestReachesCartWithOneProduct(page: Page): Promise<{
+  shopPage: ShopPage;
+  cartPage: CartPage;
+}> {
+  const shopPage = new ShopPage(page);
+  const cartPage = new CartPage(page);
+
+  await page.goto('/');
+  await dismissConsent(page);
+
+  // The shop module tile on the home page ("E-commerce Flow").
+  await page.getByTestId('tile-e-commerce-flow').click();
+  await expect(page).toHaveTitle(SHOP_TITLE);
+
+  await shopPage.addFirstProductToCart();
+  // The add is an async request — wait for the badge before navigating away.
+  await expect(shopPage.cartCount).toHaveText('1');
+
+  await shopPage.cartLink.click();
+  await expect(page).toHaveTitle(CART_TITLE);
+  await expect(cartPage.heading).toHaveText('Your cart');
+  return { shopPage, cartPage };
+}
+
+/** Assert the stepper advertises all five steps and marks the current one. */
+async function expectStep(page: Page, stepNumber: number): Promise<void> {
+  const stepper = page.getByTestId('checkout-stepper');
+  await expect(stepper).toBeVisible();
+
+  for (const label of CHECKOUT_STEPS) {
+    await expect(stepper).toContainText(label);
+  }
+  // The page header states which step of five is showing.
+  await expect(page.getByText(`Checkout · Step ${stepNumber} of 5`)).toBeVisible();
+  await expect(page).toHaveURL(new RegExp(`/shop/checkout/${stepNumber}$`));
+}
+
+test('Checkout walks five steps and confirms the order number', async ({ page }) => {
+  await guestReachesCartWithOneProduct(page);
+  const checkoutPage = new CheckoutPage(page);
+  const cartPage = new CartPage(page);
+
+  // Cart -> checkout (step 1).
+  await cartPage.proceedToCheckoutButton.click();
+  await expect(page).toHaveTitle(CHECKOUT_TITLE);
+
+  // Step 1 of 5 — shipping address (all fields required).
+  await expectStep(page, 1);
+  await checkoutPage.fillShipping(
+    SHIPPING.name,
+    SHIPPING.phone,
+    SHIPPING.address,
+    SHIPPING.city,
+    SHIPPING.zip,
+  );
+  await checkoutPage.goToNextStep();
+
+  // Step 2 of 5 — billing (same as shipping is pre-selected).
+  await expectStep(page, 2);
+  await expect(page.getByTestId('ck-same')).toBeChecked();
+  await checkoutPage.goToNextStep();
+
+  // Step 3 of 5 — shipping method (Standard is pre-selected).
+  await expectStep(page, 3);
+  await expect(page.getByTestId('ship-std')).toBeChecked();
+  await checkoutPage.goToNextStep();
+
+  // Step 4 of 5 — payment with the sandbox test card.
+  await expectStep(page, 4);
+  await checkoutPage.fillCardPayment();
+  await checkoutPage.goToNextStep();
+
+  // Step 5 of 5 — review, accept terms, place the order.
+  await expectStep(page, 5);
+  await checkoutPage.acceptTerms();
+  await checkoutPage.placeOrderButton.click();
+
+  // Order confirmation page.
+  await expect(page).toHaveURL(/\/shop\/order\/ORD-\d+$/);
+  await expect(checkoutPage.confirmationHeading).toHaveText(ORDER_CONFIRMED_HEADING);
+
+  // The confirmation shows the order number, matching the URL.
+  const orderNumber = await checkoutPage.orderNumber();
+  expect(orderNumber).toMatch(/^ORD-\d+$/);
+  await expect(page.getByText(orderNumber)).toBeVisible();
+});
+
+test('Checkout: the cart is empty after an order is placed', async ({ page }) => {
+  await guestReachesCartWithOneProduct(page);
+  const checkoutPage = new CheckoutPage(page);
+  const cartPage = new CartPage(page);
+
+  await cartPage.proceedToCheckoutButton.click();
+  await expectStep(page, 1);
+  await checkoutPage.fillShipping(
+    SHIPPING.name,
+    SHIPPING.phone,
+    SHIPPING.address,
+    SHIPPING.city,
+    SHIPPING.zip,
+  );
+  await checkoutPage.goToNextStep();
+  await expectStep(page, 2);
+  await checkoutPage.goToNextStep();
+  await expectStep(page, 3);
+  await checkoutPage.goToNextStep();
+  await expectStep(page, 4);
+  await checkoutPage.fillCardPayment();
+  await checkoutPage.goToNextStep();
+  await expectStep(page, 5);
+  await checkoutPage.acceptTerms();
+  await checkoutPage.placeOrderButton.click();
+
+  // Order placed.
+  await expect(page).toHaveURL(/\/shop\/order\/ORD-\d+$/);
+
+  // Back to the shop through the confirmation's "Continue shopping" CTA.
+  await page.getByRole('link', { name: 'Continue shopping' }).click();
+  await expect(page).toHaveTitle(SHOP_TITLE);
+
+  // The header badge is back to zero and the cart page shows its empty state.
+  const shopPage = new ShopPage(page);
+  await expect(shopPage.cartCount).toHaveText('0');
+  await shopPage.cartLink.click();
+  await expect(page).toHaveTitle(CART_TITLE);
+  await cartPage.expectEmpty();
+});
