@@ -0,0 +1,86 @@
+import { test, expect } from '../fixtures/fixtures';
+import { dismissConsent } from '../helpers/consent';
+import { loginAsManagerViaUi } from '../helpers/auth';
+import { ADMIN_TITLE } from '../pages/AdminDashboardPage';
+
+/**
+ * REQ-SHOP-04 "Shop coupons and checkout" — Admin (source SRC-4).
+ *
+ *   The Admin dashboard is available to admins and managers.
+ *
+ * Journeys: both privileged seeded accounts (manager, admin) sign in through
+ * the home page and open the Admin Dashboard from the sidebar link, exactly
+ * as a signed-in user would. Guests must not reach it.
+ *
+ * Credentials are the seeded demo accounts of this practice site and are
+ * entered through the sign-in form (no /debug or /api access is used).
+ */
+
+const SEEDED_ADMIN = { username: 'admin', password: 'admin123' };
+/** Demo OTP shown on the 2FA page ("Hint for tests: 123456"). */
+const DEMO_OTP = '123456';
+
+/** Sign in as the seeded admin, including its 2FA step, from the home page. */
+async function loginAsAdminViaUi(page: import('@playwright/test').Page): Promise<void> {
+  await page.goto('/');
+  await dismissConsent(page);
+
+  await page.getByTestId('header-login').click();
+  await expect(page.getByTestId('username-input')).toBeVisible();
+
+  await page.getByTestId('username-input').fill(SEEDED_ADMIN.username);
+  await page.getByTestId('password-input').fill(SEEDED_ADMIN.password);
+  await page.getByTestId('login-submit').click();
+
+  // The admin account always passes through the OTP step.
+  await expect(page.getByTestId('otp-input')).toBeVisible({ timeout: 15000 });
+  await page.getByTestId('otp-input').fill(DEMO_OTP);
+  await page.getByTestId('otp-submit').click();
+
+  await expect(page.getByTestId('user-pill')).toBeVisible({ timeout: 15000 });
+}
+
+/** Open the Admin Dashboard from the sidebar link. */
+async function openAdminDashboard(page: import('@playwright/test').Page): Promise<void> {
+  await page.getByTestId('nav-admin').click();
+  await expect(page).toHaveURL(/\/admin$/);
+  await expect(page).toHaveTitle(ADMIN_TITLE);
+  await expect(page.getByTestId('page-title')).toHaveText('Admin Dashboard');
+}
+
+test('Admin dashboard is available to managers', async ({ page, loginPage }) => {
+  await loginAsManagerViaUi(loginPage);
+
+  await openAdminDashboard(page);
+
+  // The dashboard's KPI cards and recent-orders table are rendered.
+  await expect(page.getByTestId('stat-users')).toHaveText(/\d+/);
+  await expect(page.getByTestId('stat-products')).toHaveText(/\d+/);
+  await expect(page.getByTestId('stat-orders')).toHaveText(/\d+/);
+  await expect(page.getByTestId('recent-orders')).toBeVisible();
+});
+
+test('Admin dashboard is available to admins', async ({ page }) => {
+  await loginAsAdminViaUi(page);
+
+  await openAdminDashboard(page);
+
+  await expect(page.getByTestId('stat-users')).toHaveText(/\d+/);
+  await expect(page.getByTestId('stat-products')).toHaveText(/\d+/);
+  await expect(page.getByTestId('stat-orders')).toHaveText(/\d+/);
+  await expect(page.getByTestId('recent-orders')).toBeVisible();
+});
+
+test('Admin dashboard is closed to guests', async ({ page }) => {
+  await page.goto('/');
+  await dismissConsent(page);
+
+  // Guest opens the Admin Dashboard module link from the home page/sidebar.
+  await page.getByTestId('nav-admin').click();
+
+  // Turned away to the sign-in page rather than shown the dashboard.
+  await expect(page).toHaveURL(/\/auth\/login$/);
+  await expect(page.getByTestId('login-submit')).toBeVisible();
+  await expect(page.getByTestId('stat-users')).toHaveCount(0);
+});
+

