+  phone: '+1 555 0100',
+  address: '42 Analytical Lane',
+  city: 'London',
+  zip: '10001',
+};
+
+/** Guest journey: home -> shop tile -> add first product -> cart. */
+async function guestReachesCartWithOneProduct(page: Page): Promise<{
+  shopPage: ShopPage;
+  cartPage: CartPage;
+}> {
+  const shopPage = new ShopPage(page);
+  const cartPage = new CartPage(page);
+
+  await page.goto('/');
+  await dismissConsent(page);
+
+  // The shop module tile on the home page ("E-commerce Flow").
+  await page.getByTestId('tile-e-commerce-flow').click();
+  await expect(page).toHaveTitle(SHOP_TITLE);
+
+  await shopPage.addFirstProductToCart();
+  // The add is an async request — wait for the badge before navigating away.
+  await expect(shopPage.cartCount).toHaveText('1');
+
+  await shopPage.cartLink.click();
+  await expect(page).toHaveTitle(CART_TITLE);
+  await expect(cartPage.heading).toHaveText('Your cart');
+  return { shopPage, cartPage };
+}
+
+/** Assert the stepper advertises all five steps and marks the current one. */
+async function expectStep(page: Page, stepNumber: number): Promise<void> {
+  const stepper = page.getByTestId('checkout-stepper');
+  await expect(stepper).toBeVisible();
+
+  for (const label of CHECKOUT_STEPS) {
+    await expect(stepper).toContainText(label);
+  }
+  // The page header states which step of five is showing.
+  await expect(page.getByText(`Checkout · Step ${stepNumber} of 5`)).toBeVisible();
+  await expect(page).toHaveURL(new RegExp(`/shop/checkout/${stepNumber}$`));
+}
+
+test('Checkout walks five steps and confirms the order number', async ({ page }) => {
+  await guestReachesCartWithOneProduct(page);
+  const checkoutPage = new CheckoutPage(page);
+  const cartPage = new CartPage(page);
+
+  // Cart -> checkout (step 1).
+  await cartPage.proceedToCheckoutButton.click();
+  await expect(page).toHaveTitle(CHECKOUT_TITLE);
+
+  // Step 1 of 5 — shipping address (all fields required).
+  await expectStep(page, 1);
+  await checkoutPage.fillShipping(
