+  await checkoutPage.goToNextStep();
+
+  // Step 2 of 5 — billing (same as shipping is pre-selected).
+  await expectStep(page, 2);
+  await expect(page.getByTestId('ck-same')).toBeChecked();
+  await checkoutPage.goToNextStep();
+
+  // Step 3 of 5 — shipping method (Standard is pre-selected).
+  await expectStep(page, 3);
+  await expect(page.getByTestId('ship-std')).toBeChecked();
+  await checkoutPage.goToNextStep();
+
