+  const cartPage = new CartPage(page);
+
+  await cartPage.proceedToCheckoutButton.click();
+  await expectStep(page, 1);
+  await checkoutPage.fillShipping(
+    SHIPPING.name,
+    SHIPPING.phone,
+    SHIPPING.address,
+    SHIPPING.city,
+    SHIPPING.zip,
+  );
+  await checkoutPage.goToNextStep();
+  await expectStep(page, 2);
+  await checkoutPage.goToNextStep();
+  await expectStep(page, 3);
+  await checkoutPage.goToNextStep();
+  await expectStep(page, 4);
+  await checkoutPage.fillCardPayment();
+  await checkoutPage.goToNextStep();
+  await expectStep(page, 5);
+  await checkoutPage.acceptTerms();
+  await checkoutPage.placeOrderButton.click();
+
+  // Order placed — assert the confirmation BEFORE navigating away, so a
+  // server-side failure surfaces here instead of as a missing-CTA timeout.
+  await expect(page).toHaveURL(/\/shop\/order\/ORD-\d+$/);
+  await expect(checkoutPage.confirmationHeading).toHaveText(ORDER_CONFIRMED_HEADING);
+
+  // Back to the shop through the confirmation's "Continue shopping" CTA.
+  await page.getByRole('link', { name: 'Continue shopping' }).click();
+  await expect(page).toHaveTitle(SHOP_TITLE);
+
+  // The header badge is back to zero and the cart page shows its empty state.
+  const shopPage = new ShopPage(page);
+  await expect(shopPage.cartCount).toHaveText('0');
+  await shopPage.cartLink.click();
+  await expect(page).toHaveTitle(CART_TITLE);
+  await cartPage.expectEmpty();
+});
