+  expect(cardTexts.length).toBeGreaterThan(0);
+  for (const text of cardTexts) {
+    expect(text).toContain('Electronics');
+  }
+
+  // Prices are in ascending order.
+  const sortedPrices = await shopPage.listedPrices();
+  expect(sortedPrices.length).toBeGreaterThan(1);
+  const ascending = [...sortedPrices].sort((a, b) => a - b);
+  expect(sortedPrices).toEqual(ascending);
