+ * overlaying the page and intercepting clicks. Any journey that starts from a
+ * fresh browser context has to dismiss it before interacting.
+ *
+ * Buttons: "Essential only" (data-testid=cookie-essential) and
+ * "Accept all" (data-testid=cookie-accept). Tests pick "Essential only" so no
+ * analytics consent is granted.
+ */
+export const COOKIE_BANNER_TEXT = 'We use cookies';
+
+export class CookieConsent {
+  /** "Essential only" button on the cookie-consent banner. */
+  readonly essentialOnlyButton;
+  /** "Accept all" button on the cookie-consent banner. */
+  readonly acceptAllButton;
+
+  constructor(private readonly page: Page) {
+    this.essentialOnlyButton = page.getByTestId('cookie-essential');
+    this.acceptAllButton = page.getByTestId('cookie-accept');
+  }
+
+  /**
+   * Dismiss the banner if it is showing. Safe to call on every page — resolves
+   * immediately when no banner is present (or it never appears).
+   */
+  async dismissIfPresent(timeout = 5000): Promise<void> {
+    const appeared = await this.essentialOnlyButton
+      .waitFor({ state: 'visible', timeout })
+      .then(() => true)
+      .catch(() => false);
+    if (!appeared) {
+      return;
+    }
+    await this.essentialOnlyButton.click();
+    await expect(this.essentialOnlyButton).toBeHidden({ timeout: 10000 });
+  }
+}
