+import { test, expect } from '../fixtures/fixtures';
+import { CookieConsent } from '../helpers/cookieConsent';
+import { loginAsAdmin, loginAsManager } from '../helpers/auth';
+
+/**
+ * REQ-SHOP-04 — Shop coupons and checkout (TestverQA Development, http://localhost:4300).
+ *
+ * Every journey here enters the way a customer does: the shop is reached from
+ * the entry page, and the cart is filled by clicking a product's "+ Add" button
+ * on /shop. No deep links into the cart, checkout or order pages.
+ *
+ * Scope of this suite is the requirement text only:
+ *   Coupons    SAVE10 -10%, WELCOME20 -20%, expired and unknown refusals
+ *   Checkout   5 steps -> confirmation showing the order number, cart emptied
+ *   Account    profile shows the join month and year
+ *   Admin      dashboard available to admins and managers
+ *
+ * Deliberately NOT done (run restrictions): no /api/reset, no password or
+ * account-settings writes, nothing deleted, /debug and /api never touched.
+ * Each test therefore builds its own cart from scratch and leaves it behind.
+ */
+
+const BASE_URL = (process.env.BASE_URL || 'http://localhost:4300').replace(/\/$/, '');
+
+/** Fill the cart from the shop page and wait for the badge to confirm the add landed. */
+async function addOneProductFromShop(
+  shopPage: import('../pages/ShopPage').ShopPage,
+  page: import('@playwright/test').Page,
+  cookieConsent: CookieConsent,
+): Promise<void> {
+  await shopPage.goto('/shop');
+  await cookieConsent.dismissIfPresent();
+  await expect(shopPage.heading).toBeVisible();
+
+  await shopPage.addFirstProductToCart();
+  // The add is an async POST — wait for the badge so the navigation cannot
+  // abort the in-flight request and leave the cart empty.
+  await expect(shopPage.cartCount).toHaveText('1');
+}
+
+/** Open the cart from the shop via its badge link (the customer's click path). */
+async function openCartFromShop(
+  shopPage: import('../pages/ShopPage').ShopPage,
+  cartPage: import('../pages/CartPage').CartPage,
+  page: import('@playwright/test').Page,
+): Promise<void> {
+  await shopPage.cartLink.click();
+  await expect(page).toHaveURL(/\/shop\/cart$/);
+  await expect(cartPage.heading).toBeVisible();
+}
+
+/** Read the subtotal/discount/total triple from the cart's order summary. */
+function expectDiscountIs(subtotal: number, discount: number, rate: number): void {
+  // Guard the arithmetic so a bad expectation cannot silently pass.
+  expect(subtotal).toBeGreaterThan(0);
+  expect(discount).toBeCloseTo(+(subtotal * rate).toFixed(2), 2);
+}
+
+// ---------------------------------------------------------------- coupons ---
+
+test('Cart: SAVE10 takes 10 percent off the cart subtotal', async ({
+  page,
+  shopPage,
+  cartPage,
+}) => {
