+import { test, expect } from '../fixtures/fixtures';
+import fs from 'node:fs';
+import path from 'node:path';
+
+/**
+ * Product Lookup — API tests for the Testver Playground REST API.
+ *
+ * Covers:
+ *  1. The saved "Product Lookup" chain: GET /api/products -> extract the first
+ *     product id -> GET /api/products/{productId} and verify the read-back.
+ *  2. The fixed data set in api/products.csv (id, expected_status, expected_name),
+ *     including the 404 not-found case.
+ *
+ * The playground state is FIXED seed data for this suite — nothing here calls
+ * POST /api/reset, so the data set stays as delivered.
+ */
+
+const API_BASE_URL = process.env.API_BASE_URL || 'http://localhost:4300';
+
+const PRODUCT_SCHEMA = {
+  type: 'object',
+  required: ['id', 'name', 'sku', 'price', 'categoryId', 'categoryName', 'stock', 'featured'],
+  properties: {
+    id: { type: 'integer' },
+    name: { type: 'string', minLength: 1 },
+    sku: { type: 'string', pattern: '^SKU-\\d{5}$' },
+    price: { type: 'number' },
+    categoryId: { type: 'integer' },
+    categoryName: { type: 'string' },
+    stock: { type: 'integer' },
+    description: { type: 'string' },
+    rating: { type: 'number' },
+    image: { type: 'string' },
+    createdAt: { type: 'string' },
+    featured: { type: 'boolean' },
+  },
+  additionalProperties: true,
+} as const;
+
+type ProductRow = {
+  id: string;
+  expected_status: string;
+  expected_name: string;
+};
+
+/** Read the fixed CSV data set (api/products.csv) without extra dependencies. */
+function readProductRows(): ProductRow[] {
+  const csvPath = path.resolve(__dirname, '..', '..', 'api', 'products.csv');
+  const [header, ...lines] = fs
+    .readFileSync(csvPath, 'utf8')
+    .split(/\r?\n/)
+    .filter((line) => line.trim().length > 0);
+  const columns = header.split(',').map((column) => column.trim());
+
+  return lines.map((line) => {
+    const values = line.split(',');
+    const row: Record<string, string> = {};
+    columns.forEach((column, index) => {
+      row[column] = (values[index] ?? '').trim();
+    });
+    return row as unknown as ProductRow;
+  });
+}
+
+test.describe('Product Lookup API', () => {
+  test('Product lookup chain: list products then fetch the extracted id', async ({ request }) => {
+    // Step 1 — list products (the collection's first chain step).
+    const listResponse = await request.get(`${API_BASE_URL}/api/products`);
+    expect(listResponse.status()).toBe(200);
+    expect(listResponse.headers()['content-type']).toContain('application/json');
+
+    const products = await listResponse.json();
+    expect(Array.isArray(products)).toBe(true);
+    expect(products.length).toBeGreaterThan(0);
+    expect(products[0]).toHaveProperty('id');
+
+    // Step 2 — extract $[0].id and look that product up again.
+    const productId: number = products[0].id;
+    const detailResponse = await request.get(`${API_BASE_URL}/api/products/${productId}`);
+    expect(detailResponse.status()).toBe(200);
+
+    const product = await detailResponse.json();
+    expect(product.id).toBe(productId);
+    expect(product.name).toBe(products[0].name);
+    expect(typeof product.sku).toBe('string');
+  });
+
+  test('Product lookup chain: the extracted id returns a complete product record', async ({
+    request,
+  }) => {
+    const listResponse = await request.get(`${API_BASE_URL}/api/products`);
+    const products = await listResponse.json();
+    const productId: number = products[0].id;
+
+    const detailResponse = await request.get(`${API_BASE_URL}/api/products/${productId}`);
+    const product = await detailResponse.json();
+
+    await expect(product).toMatchSchemaShape(PRODUCT_SCHEMA);
+  });
+
+  const rows = readProductRows();
