+        const response = await request.get(`${API_BASE_URL}/api/products/${row.id}`);
+        expect(response.status()).toBe(Number(row.expected_status));
+
+        const product = await response.json();
+        expect(String(product.id)).toBe(row.id);
+        expect(product.name).toBe(row.expected_name);
+        await expect(product).toMatchSchemaShape(PRODUCT_SCHEMA);
+      });
+    } else {
+      test(`Product lookup: csv case id ${row.id} is not found`, async ({ request }) => {
+        const response = await request.get(`${API_BASE_URL}/api/products/${row.id}`);
+        expect(response.status()).toBe(Number(row.expected_status));
+        expect(response.headers()['content-type']).toContain('application/json');
+
+        const body = await response.json();
+        expect(body).toEqual({ error: 'not found' });
+        expect(body).not.toHaveProperty('id');
+        expect(body).not.toHaveProperty('name');
+      });
+    }
+  }
