+
+/**
+ * Shared helpers for the Product Lookup API tests.
+ *
+ * The playground API is the Testver in-memory REST server; its base URL is
+ * configurable per environment (API_BASE_URL) so the same spec runs against
+ * Development (default), staging, or any other deployment.
+ */
+export const API_BASE_URL = process.env.API_BASE_URL || 'http://localhost:4300';
+
+/** One row of the fixed data set in api/products.csv. */
+export type ProductRow = {
+  id: string;
+  expected_status: string;
+  expected_name: string;
+};
+
+/**
+ * Read the fixed CSV data set (api/products.csv) with no extra dependency.
+ * Header row names the columns: id, expected_status, expected_name.
+ */
+export function readProductRows(): ProductRow[] {
+  const csvPath = path.resolve(__dirname, '..', '..', 'api', 'products.csv');
+  const lines = fs
+    .readFileSync(csvPath, 'utf8')
+    .split(/\r?\n/)
+    .filter((line) => line.trim().length > 0);
