import { expect } from '@playwright/test';
import fs from 'node:fs';
import path from 'node:path';

/**
 * Shared helpers for the Product Lookup API tests.
 *
 * The playground API is the Testver in-memory REST server; its base URL is
 * configurable per environment (API_BASE_URL) so the same spec runs against
 * Development (default), staging, or any other deployment.
 */
export const API_BASE_URL = process.env.API_BASE_URL || 'http://localhost:4300';

/** One row of the fixed data set in api/products.csv. */
export type ProductRow = {
  id: string;
  expected_status: string;
  expected_name: string;
};

/**
 * Read the fixed CSV data set (api/products.csv) with no extra dependency.
 * Header row names the columns: id, expected_status, expected_name.
 */
export function readProductRows(): ProductRow[] {
  const csvPath = path.resolve(__dirname, '..', '..', 'api', 'products.csv');
  const lines = fs
    .readFileSync(csvPath, 'utf8')
    .split(/\r?\n/)
    .filter((line) => line.trim().length > 0);

  const columns = lines[0].split(',').map((column) => column.trim());

  return lines.slice(1).map((line) => {
    const values = line.split(',');
    const row: Record<string, string> = {};
    columns.forEach((column, index) => {
      row[column] = (values[index] ?? '').trim();
    });
    return row as unknown as ProductRow;
  });
}

/**
 * Assert the response body is a complete product record, matching the shape
 * documented in api/openapi-v1.json (GET /api/products/{id}).
 */
export function assertProductRecord(product: any): void {
  expect(product, 'product body should be a JSON object').toBeInstanceOf(Object);
  expect(Array.isArray(product)).toBe(false);

  expect(product.id).toEqual(expect.any(Number));
  expect(Number.isInteger(product.id)).toBe(true);
  expect(product.name).toEqual(expect.any(String));
  expect(product.name.length).toBeGreaterThan(0);
  expect(product.sku).toMatch(/^SKU-\d{5}$/);
  expect(product.price).toEqual(expect.any(Number));
  expect(product.categoryId).toEqual(expect.any(Number));
  expect(product.categoryName).toEqual(expect.any(String));
  expect(product.stock).toEqual(expect.any(Number));
  expect(product.featured).toEqual(expect.any(Boolean));
}

